from produire import produire,paras,table,steps
from medicaments import coamoxicilline
parts=[
('L’abcès périamygdalien est une collection purulente de l’espace autour de l’amygdale. Les {distinctions anatomiques} le séparent d’une amygdalite simple et d’un phlegmon sans collection.',paras('L’espace périamygdalien se situe entre capsule amygdalienne et muscle constricteur supérieur du pharynx. Une inflammation sans pus ne requiert pas le même geste qu’une collection drainable.')),
('Il touche notamment adolescents et jeunes adultes, mais n’est pas limité à ces âges. Les {contextes favorisants} incluent infection amygdalienne et facteurs buccodentaires.',paras('Un abcès peut apparaître même après une antibiothérapie pour une angine. Tabagisme et infection parodontale peuvent contribuer ; leur absence n’exclut pas une collection.')),
('L’infection est souvent polymicrobienne, avec germes aérobies et anaérobies. Les {mécanismes d’extension} expliquent le risque respiratoire et cervical.',paras('La collection déplace les structures du voile et peut provoquer un spasme des muscles masticateurs. L’extension peut atteindre les espaces para- ou rétropharyngés et, dans les formes graves, le médiastin.')),
('L’évaluation des voies aériennes est prioritaire. Les {signes de gravité} imposent une mobilisation hospitalière immédiate.',paras('Dyspnée, stridor, incapacité à avaler la salive, sepsis, gonflement cervical, déshydratation ou altération de conscience imposent une prise en charge urgente. Une imagerie ne doit pas retarder la sécurisation des voies aériennes.')),
('La douleur est souvent intense, unilatérale et aggravée à la déglutition. Les {questions ciblées} précisent évolution et possibilité de geste.',paras('Demander fièvre, otalgie du même côté, modification de voix, trismus et capacité à boire. Relever antibiotiques déjà reçus, allergies, anticoagulants, immunodépression et antécédents d’abcès ou d’angines répétées.')),
('L’examen recherche bombement du voile et asymétrie périamygdalienne. Les {signes caractéristiques} sont utiles sans être tous obligatoires.',paras('Une luette déviée du côté opposé, une voix étouffée et un trismus soutiennent la suspicion. Le trismus peut manquer, notamment chez l’enfant ; il n’est pas à lui seul une preuve absolue d’abcès. Examiner prudemment et éviter une manipulation forcée.')),
('Le {diagnostic différentiel} comprend d’autres infections profondes et une tumeur surinfectée. Le tableau clinique seul ne localise pas toujours la collection.',table(['Profil','À rechercher'],[['Inflammation sans collection.','Phlegmon périamygdalien.'],['Torticolis, douleur cervicale ou bombement postérieur.','Abcès rétropharyngé ou parapharyngé.'],['Dégradation rapide avec gêne respiratoire.','Épiglottite ou autre obstruction haute.'],['Évolution atypique, masse persistante.','Néoplasie surinfectée.'],['Reprise fébrile et tuméfaction cervicale.','Syndrome de Lemierre selon le contexte.']])) ,
('Le diagnostic de collection peut être confirmé par un geste spécialisé ou par imagerie. Les {limites de la ponction} évitent une fausse exclusion.',paras('La ponction réalisée par une équipe formée peut retrouver du pus. Une ponction négative n’exclut pas un abcès postérieur ou inférieur ; ne pas multiplier les gestes à l’aveugle.')),
('Le bilan dépend de la gravité et de la qualité de l’examen. Les {examens complémentaires} orientent drainage et traitement.',paras('Un scanner cervical injecté est notamment utile si examen limité, ponction négative avec suspicion persistante ou extension profonde. Biologie et hémocultures dépendent de l’état général ; le pus prélevé peut être envoyé en microbiologie. Une suspicion tumorale nécessite l’évaluation histologique appropriée.')),
('L’{arbre de décision} relie urgence, confirmation et contrôle du foyer. Une simple ordonnance ambulatoire ne suffit pas à tout abcès.',steps('Évaluer respiration, hydratation et sepsis, puis obtenir un avis ORL urgent.', 'Confirmer et localiser la collection par examen, geste spécialisé ou imagerie si nécessaire.', 'Drainer selon la situation et le protocole de l’équipe ; l’incision-drainage ou une amygdalectomie à chaud peuvent être retenues.', 'Associer antibiothérapie et soins de support, puis adapter aux résultats et à l’évolution.')),
('Le traitement associe contrôle du foyer, antibiothérapie et soins de support. Les {modalités hospitalières} sont adaptées à la gravité et aux contre-indications.',paras('L’article du CHUV décrit drainage et couverture bactérienne incluant aérobies et anaérobies, avec hospitalisation et relais oral selon l’évolution. La corticothérapie adjuvante n’est pas un substitut au drainage ; son utilisation dépend du protocole et du patient.', '@@MEDICAMENTS@@')),
('Le {suivi après traitement} vérifie disparition de l’infection et reprise des apports. Les récidives et les anomalies persistantes nécessitent un bilan ORL.',paras('Réévaluer rapidement si fièvre, douleur, gonflement ou gêne respiratoire réapparaissent. Une amygdalectomie ultérieure ou dans le temps aigu se discute selon les antécédents et la stratégie de l’équipe ; une asymétrie persistante ne doit pas être attribuée indéfiniment à l’infection.')),
('Trismus, voix étouffée et douleur unilatérale doivent faire suspecter un abcès. La respiration prime sur le scanner. Une ponction négative ne suffit pas à exclure une collection. Drainage et antibiothérapie sont complémentaires.','')]
quiz=[('Un phlegmon contient-il nécessairement une collection ?','Non : il peut s’agir d’une inflammation sans pus collecté.'),('L’abcès est-il toujours dû à un seul streptocoque ?','Non : il est souvent polymicrobien.'),('Un antibiotique antérieur exclut-il un abcès ?','Non.'),('Vers quel côté la luette peut-elle être déviée ?','Vers le côté opposé à la collection.'),('L’absence de trismus chez l’enfant exclut-elle ?','Non.'),('Le trismus est-il à lui seul une preuve absolue ?','Non : il faut confronter l’ensemble des éléments.'),('Que faire devant stridor et hypersialorrhée ?','Mobiliser immédiatement la prise en charge des voies aériennes.'),('Le scanner doit-il retarder cette prise en charge ?','Non.'),('Une ponction négative élimine-t-elle tout abcès ?','Non : une collection postérieure ou inférieure reste possible.'),('Quand l’imagerie est-elle particulièrement utile ?','Examen limité, doute persistant ou extension profonde suspectée.'),('Les antibiotiques remplacent-ils toujours le drainage ?','Non.'),('Pourquoi couvrir les anaérobies ?','Ils participent fréquemment à l’infection polymicrobienne.'),('La dose injectable adulte peut-elle être transposée directement à l’enfant ?','Non : poids, ratios de préparation et gravité doivent être pris en compte.'),('Que faire devant une masse persistante après traitement ?','Rechercher une autre cause, notamment tumorale, avec l’ORL.')]
produire(9,parts,quiz,(5,26,27),coamoxicilline)
